CREATE TABLE `tenants` (`id` VARCHAR(36) NOT NULL,`slug` VARCHAR(120) NOT NULL,`name` VARCHAR(160) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),`updatedAt` TIMESTAMP(0) NOT NULL,UNIQUE INDEX `IDX_tenants_slug`(`slug`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `users` (`id` VARCHAR(36) NOT NULL,`email` VARCHAR(180) NULL,`phone` VARCHAR(32) NULL,`countryCode` VARCHAR(8) NULL,`name` VARCHAR(120) NOT NULL,`passwordHash` VARCHAR(255) NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),`updatedAt` TIMESTAMP(0) NOT NULL,UNIQUE INDEX `UQ_users_email`(`email`),INDEX `IDX_users_active_created_at`(`active`,`createdAt`),UNIQUE INDEX `UQ_users_country_phone`(`countryCode`,`phone`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tenant_memberships` (`userId` VARCHAR(36) NOT NULL,`tenantId` VARCHAR(36) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),`updatedAt` TIMESTAMP(0) NOT NULL,INDEX `IDX_memberships_tenant_active_created_at`(`tenantId`,`active`,`createdAt`),PRIMARY KEY (`userId`,`tenantId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `roles` (`id` VARCHAR(36) NOT NULL,`tenantId` VARCHAR(36) NULL,`code` VARCHAR(50) NOT NULL,`name` VARCHAR(100) NOT NULL,`description` VARCHAR(255) NOT NULL DEFAULT '',`builtIn` BOOLEAN NOT NULL DEFAULT false,`enabled` BOOLEAN NOT NULL DEFAULT true,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),`updatedAt` TIMESTAMP(0) NOT NULL,INDEX `IDX_roles_tenant_enabled_code`(`tenantId`,`enabled`,`code`),UNIQUE INDEX `UQ_roles_tenant_code`(`tenantId`,`code`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `permissions` (`id` VARCHAR(36) NOT NULL,`code` VARCHAR(100) NOT NULL,`name` VARCHAR(100) NOT NULL,`description` VARCHAR(255) NOT NULL DEFAULT '',`builtIn` BOOLEAN NOT NULL DEFAULT false,`enabled` BOOLEAN NOT NULL DEFAULT true,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),`updatedAt` TIMESTAMP(0) NOT NULL,UNIQUE INDEX `UQ_permissions_code`(`code`),INDEX `IDX_permissions_enabled_code`(`enabled`,`code`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `role_permissions` (`roleId` VARCHAR(36) NOT NULL,`permissionId` VARCHAR(36) NOT NULL,INDEX `IDX_role_permissions_permission_id`(`permissionId`),PRIMARY KEY (`roleId`,`permissionId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `user_role_assignments` (`userId` VARCHAR(36) NOT NULL,`tenantId` VARCHAR(36) NOT NULL,`roleId` VARCHAR(36) NOT NULL,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),INDEX `IDX_user_roles_tenant_role`(`tenantId`,`roleId`),INDEX `IDX_user_roles_role_id`(`roleId`),PRIMARY KEY (`userId`,`tenantId`,`roleId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `refresh_tokens` (`id` VARCHAR(36) NOT NULL,`tenantId` VARCHAR(36) NOT NULL,`userId` VARCHAR(36) NOT NULL,`tokenHash` VARCHAR(64) NOT NULL,`expiresAt` TIMESTAMP(0) NOT NULL,`revokedAt` TIMESTAMP(0) NULL,`replacedByTokenId` VARCHAR(36) NULL,`userAgent` VARCHAR(512) NULL,`ipAddress` VARCHAR(64) NULL,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),`updatedAt` TIMESTAMP(0) NOT NULL,UNIQUE INDEX `IDX_refresh_tokens_token_hash`(`tokenHash`),INDEX `IDX_refresh_tokens_tenant_id`(`tenantId`),INDEX `IDX_refresh_tokens_user_id`(`userId`),INDEX `IDX_refresh_tokens_user_revoked_expires`(`userId`,`revokedAt`,`expiresAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `outbox_events` (`id` VARCHAR(36) NOT NULL,`tenantId` VARCHAR(36) NOT NULL,`aggregateType` VARCHAR(80) NOT NULL,`aggregateId` VARCHAR(36) NOT NULL,`routingKey` VARCHAR(120) NOT NULL,`payload` JSON NOT NULL,`createdAt` TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),INDEX `IDX_outbox_events_tenant_created_at`(`tenantId`,`createdAt`),INDEX `IDX_outbox_events_aggregate`(`aggregateType`,`aggregateId`),INDEX `IDX_outbox_events_routing_key_created_at`(`routingKey`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `processed_events` (`eventId` VARCHAR(36) NOT NULL,`routingKey` VARCHAR(120) NOT NULL,`processedAt` TIMESTAMP(0) NOT NULL,`expiresAt` TIMESTAMP(0) NOT NULL,INDEX `IDX_processed_events_expires`(`expiresAt`),PRIMARY KEY (`eventId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
